export default "import {\n  EmbeddedScene,\n  PanelBuilders,\n  SceneAppPage,\n  SceneAppPageState,\n  SceneDataTransformer,\n  SceneFlexItem,\n  SceneFlexLayout,\n} from '@grafana/scenes';\nimport { getQueryRunnerWithRandomWalkQuery, getEmbeddedSceneDefaults } from './utils';\n\nexport function getQueryCancellationTest(defaults: SceneAppPageState) {\n  return new SceneAppPage({\n    ...defaults,\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        key: 'Flex layout embedded scene',\n        $data: getQueryRunnerWithRandomWalkQuery(\n          { scenarioId: 'slow_query', stringInput: '10s' },\n          { maxDataPointsFromWidth: false }\n        ),\n        body: new SceneFlexLayout({\n          direction: 'column',\n          children: [\n            new SceneFlexLayout({\n              direction: 'row',\n              children: [\n                new SceneFlexItem({\n                  minWidth: '20%',\n                  body: PanelBuilders.timeseries().setTitle('Global query').build(),\n                }),\n                new SceneFlexItem({\n                  minWidth: '20%',\n                  body: PanelBuilders.timeseries()\n                    .setTitle('Local query')\n                    .setData(\n                      getQueryRunnerWithRandomWalkQuery(\n                        { scenarioId: 'slow_query', stringInput: '10s' },\n                        { maxDataPointsFromWidth: false }\n                      )\n                    )\n                    .build(),\n                }),\n                new SceneFlexItem({\n                  minWidth: '20%',\n                  body: PanelBuilders.stat()\n                    .setTitle('Local query via transformation')\n                    .setData(\n                      new SceneDataTransformer({\n                        $data: getQueryRunnerWithRandomWalkQuery(\n                          { scenarioId: 'slow_query', stringInput: '15s' },\n                          { maxDataPointsFromWidth: true }\n                        ),\n                        transformations: [\n                          {\n                            id: 'reduce',\n                            options: {\n                              reducers: ['mean'],\n                            },\n                          },\n                        ],\n                      })\n                    )\n                    .build(),\n                }),\n                new SceneFlexItem({\n                  minWidth: '20%',\n                  body: PanelBuilders.stat()\n                    .setTitle('Global query via transformation')\n                    .setData(\n                      new SceneDataTransformer({\n                        transformations: [\n                          {\n                            id: 'reduce',\n                            options: {\n                              reducers: ['mean'],\n                            },\n                          },\n                        ],\n                      })\n                    )\n                    .build(),\n                }),\n                new SceneFlexItem({\n                  minWidth: '20%',\n                  body: PanelBuilders.stat()\n                    .setTitle('Transformed transformation')\n                    .setData(\n                      new SceneDataTransformer({\n                        transformations: [\n                          {\n                            id: 'calculateField',\n                            options: {\n                              mode: 'binary',\n                              reduce: {\n                                reducer: 'sum',\n                              },\n                              binary: {\n                                left: 'A-series',\n                                reducer: 'sum',\n                                operator: '*',\n                                right: '2',\n                              },\n                            },\n                          },\n                        ],\n                      })\n                    )\n                    .build(),\n                }),\n              ],\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n";